#include "led_cases.inc"
#include "USBHIDKeyboard.h"
int main(int argc,char**argv){if(argc!=2)return 2;if(argv[1][0]!='C')return historical_led_main(argc,argv);try{
 mscMock::reset();mock::reset();setup();check(startupControlledReady,"controlled setup");check(route_u::bindOwner(),"owner");lower::reset();led_mock::nowUs=0;auto r=req();std::string id=argv[1];
 if(id=="C01"){put("/x.txt","DELAY 500\nHOLD CAPSLOCK\nDELAY 500\nRELEASE CAPSLOCK\nSTRING after\n");start();done();handleStatus(&r);check(route_u::status().reason==route_u::Reason::Capability&&lower::count==0,"composed adapter explicitly rejects HOLD before HID");check(r.response.indexOf("\"routeBReason\":5")>=0,"unsupported long Caps attempt is visible terminal evidence");}
 else if(id=="C02"){put("/x.txt","CAPSLOCK\n");start();done();auto p=presses();check(!p.empty()&&lower::calls[p[0]].bytes[2]==0x39,"Caps exact usage through actual selected runtime");}
 else if(id=="C03"){uint8_t mask=2;mockKeyboard->_onOutput(1,&mask,1);auto s=led_return::snapshot(0);check(s.callbacks==1&&s.observed&&s.mask==2,"actual derived keyboard callback reaches receiver");}
 else if(id=="C04"){uint8_t mask=2;mockKeyboard->_onOutput(0,&mask,1);auto s=led_return::snapshot(0);check(s.callbacks==1&&s.rejected==1&&!s.observed,"unsupported ID not normalized by guess");}
 else if(id=="C05"){mockKeyboard->_onOutput(1,nullptr,0);check(led_return::snapshot(0).callbacks==1&&led_return::snapshot(0).rejected==1,"null bounds callback counter");}
 else if(id=="C06"){r.query["engine"]={"routeb"};r.query["s"]={"x.txt"};put("/x.txt","STRING a\n");handleRunScript(&r);check(r.code==202&&r.response.indexOf("\"requestId\":\"")>=0&&r.response.indexOf("queued")>=0,"correlated admission not completed");auto n=route_u::status().request;done();handleStatus(&r);check(r.response.indexOf("\"routeBReason\":1")>=0&&route_u::status().request==n,"same terminal request retained");}
 else if(id=="C07"){r.query["engine"]={"routeb"};r.query["s"]={"missing.txt"};handleRunScript(&r);check(r.code==202,"accepted prior to capture");done();handleStatus(&r);check(r.response.indexOf("\"routeBReason\":3")>=0,"file failure visible after admission");}
 else if(id=="C08"){put("/x.txt","STRING first\nNO_SUCH_COMMAND\n");start();done();handleStatus(&r);check(route_u::status().reason!=route_u::Reason::Completed&&r.response.indexOf("\"routeBLine\":2")>=0&&presses().empty(),"compiler line terminal and zero output");}
 else if(id=="C09"){put("/x.txt","STRING BAD\n");start();handleStop(&r);done();check(presses().empty()&&route_u::status().reason==route_u::Reason::Cancelled,"queued STOP no output");}
 else if(id=="C10"){put("/x.txt","CAPSLOCK\nDELAY 2000\n");start();for(int i=0;i<500&&presses().empty();++i)tick();check(!presses().empty(),"Caps transient press reached local transport");handleStop(&r);done();check(route_u::status().reason==route_u::Reason::Cancelled&&!hid_backend::hasPersistent()&&lower::calls[lower::count-1].bytes[2]==0,"Caps transient cancelled with local clear, host release unproven");}
 else if(id=="C11"){put("/x.txt","STRING BAD\n");start();auto rr=req();rr.body["s"]={"x.txt"};handleDeleteScript(&rr);check(rr.code==409,"delete denied while owned");route_u::stop();done();}
 else if(id=="C12"){put("/x.txt","REM temp\n");r.body["s"]={"x.txt"};handleDeleteScript(&r);storage::Ref ref;storage::parseRef("x.txt",ref);check(r.code==200&&!storage::exists(ref),"confirmed temporary file delete");}
 else if(id=="C13"){put("/x.txt","REM keep\n");r.body["s"]={"../x.txt"};handleDeleteScript(&r);check(r.code==400,"traversal rejected");}
 else if(id=="C14"){put("/x.txt","REM keep\n");r.headers.clear();r.body["s"]={"x.txt"};handleDeleteScript(&r);storage::Ref ref;storage::parseRef("x.txt",ref);check(r.code==401&&storage::exists(ref),"unauth delete preserves file");}
 else if(id=="C15"){r.body["s"]={"examples/hello.txt"};handleDeleteScript(&r);check(r.code==404,"firmware-only example not deleted");}
 else if(id=="C16"){std::string text="\xef\xbb\xbf" "DELAY 2000\r\nSTRING a\n";r.body["name"]={"exact.txt"};r.body["content"]={text};handleSaveScript(&r);check(r.code==200,"save synthetic source");auto q=req();q.query["s"]={"exact.txt"};handleGetScript(&q);check(q.code==200&&q.response==text,"first bytes BOM CRLF preserved by actual endpoints");}
 else if(id=="C17"){r.path="/led-test/data";server.dispatch("/led-test/data",HTTP_GET,&r);check(r.code==409&&r.response.indexOf("No verified")>=0,"incomplete data route is not JSON snapshot");}
 else if(id=="C18"){report(0);led_return::start(0);feed();r.path="/led-test/data";server.dispatch("/led-test/data",HTTP_GET,&r);check(r.code==200&&r.response=="EVILDUCK TEST 123"&&r.response.length()==17,"exact registered leaf bytes");}
 else if(id=="C19"){r.path="/led-test/unknown";server.dispatch("/led-test/unknown",HTTP_GET,&r);check(r.code==404,"base route cannot succeed for an unknown subpath");}
 else if(id=="C21"){storage::Ref sd,keep;storage::parseRef("sd:temporary.txt",sd);storage::parseRef("keep.txt",keep);check(storage::writeFile(sd,"REM sd temp")&&storage::writeFile(keep,"REM keep"),"temporary synthetic volumes");r.body["s"]={"sd:temporary.txt"};handleDeleteScript(&r);check(r.code==200&&!storage::exists(sd)&&storage::exists(keep),"authenticated SD target deleted, other file preserved");}
 else if(id=="C22"){put("/x.txt","DELAY 500\nSTRING BAD\n");r.query["engine"]={"routeb"};r.query["s"]={"x.txt"};handleRunScript(&r);auto request=route_u::status().request;handleRunScript(&r);check(r.code==409&&route_u::status().request==request,"second run refused without replay or ID change");handleStop(&r);done();check(route_u::status().reason==route_u::Reason::Cancelled&&presses().empty(),"STOP cancels only accepted run");}
 else if(id=="C20"){Holder h;handleLibrary(&r);check(r.code==409,"contention is busy not unauthorized");}
 else check(false,"unknown");std::cout<<"PASS "<<id<<" ("<<assertions<<" assertions)\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<argv[1]<<": "<<e.what()<<" ("<<assertions<<")\n";return 1;}}
